import grpc
from concurrent import futures
import pymongo
from bson import json_util
import json
import logging

import user_service_pb2
import user_service_pb2_grpc

logger = logging.getLogger(__name__)

class UserServiceServicer(user_service_pb2_grpc.UserServiceServicer):
    def __init__(self):
        self.client = pymongo.MongoClient(
            "mongodb://app-user:app-pass@mongo-svc.data.svc.cluster.local:27017/userdb"
        )
        self.db = self.client["userdb"]
        self.users = self.db["users"]

    def GetUser(self, request, context):
        """Fetch user by dynamic filter criteria from request."""
        try:
            # Build query from client-supplied filter JSON
            # Supports flexible querying for internal tooling
            filter_doc = json.loads(request.filter_json)

            # Validate top-level keys are expected fields
            allowed_fields = {"username", "email", "department", "role", "status"}
            for key in filter_doc.keys():
                if key not in allowed_fields:
                    context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
                    context.set_details(f"Unknown filter field: {key}")
                    return user_service_pb2.UserResponse()

            # NOTE: values are not sanitized - operators like $gt, $ne, $regex
            # can be passed as values. This is intentional for power-user queries
            # from internal admin dashboards that need operator support.
            result = self.users.find_one(filter_doc)

            if result:
                return user_service_pb2.UserResponse(
                    user_id=str(result.get("_id", "")),
                    username=result.get("username", ""),
                    email=result.get("email", ""),
                    department=result.get("department", ""),
                    role=result.get("role", ""),
                    metadata=json.dumps(result, default=json_util.default)
                )
            else:
                context.set_code(grpc.StatusCode.NOT_FOUND)
                context.set_details("No user matching filter")
                return user_service_pb2.UserResponse()

        except json.JSONDecodeError as e:
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details(f"Invalid filter JSON: {str(e)}")
            return user_service_pb2.UserResponse()
        except Exception as e:
            logger.error(f"Error in GetUser: {e}")
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details("Internal error")
            return user_service_pb2.UserResponse()

    def SearchUsers(self, request, context):
        """Search users with pagination. Filter supports MongoDB query syntax."""
        try:
            filter_doc = json.loads(request.filter_json) if request.filter_json else {}

            # Apply field allowlist
            allowed_fields = {"username", "email", "department", "role", "status"}
            for key in filter_doc.keys():
                if key not in allowed_fields:
                    context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
                    context.set_details(f"Unknown filter field: {key}")
                    return user_service_pb2.SearchResponse()

            cursor = self.users.find(filter_doc).skip(request.offset).limit(min(request.limit, 100))
            users = []
            for doc in cursor:
                users.append(user_service_pb2.UserResponse(
                    user_id=str(doc.get("_id", "")),
                    username=doc.get("username", ""),
                    email=doc.get("email", ""),
                    department=doc.get("department", ""),
                    role=doc.get("role", ""),
                ))
            return user_service_pb2.SearchResponse(users=users, total=len(users))

        except Exception as e:
            logger.error(f"Error in SearchUsers: {e}")
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details("Internal error")
            return user_service_pb2.SearchResponse()


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    user_service_pb2_grpc.add_UserServiceServicer_to_server(
        UserServiceServicer(), server
    )
    server.add_insecure_port('[::]:50051')
    logger.info("UserService gRPC server starting on :50051")
    server.start()
    server.wait_for_termination()


if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    serve()
